 for r in range(h):
  for c in range(w):
   if not grid[r][c] or (r,c) in seen: continue
   st=[(r,c)]; seen.add((r,c)); cells=[]
   while st:
    y,x=st.pop(); cells.append((y,x))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      if not (dy or dx): continue
      p=(y+dy,x+dx)
      if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]] and p not in seen: seen.add(p);st.append(p)
   out.append(cells)
 return out
